// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address caller, address from, address to, uint256 v) public {
        vm.assume(to != address(0));
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = to;
        vm.prank(caller);
        bool ok;
        try c.transfer(from, address(reverter), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "transfer must not succeed when the low-level call fails");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
